CREATE COLUMN TABLE "TEST_AP"."OMGP" ("AbsEntry" INTEGER CS_INT NOT NULL , "MatGrp" NVARCHAR(3) NOT NULL , "Descrip" NVARCHAR(70), "LogInstanc" INTEGER CS_INT, "UserSign2" SMALLINT CS_INT, "UpdateDate" LONGDATE CS_LONGDATE, PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OMGP_CODE" ON "TEST_AP"."OMGP" ( "MatGrp" ASC )